el.setAttribute('aria-label',p.name+' Content Calendar');
el.innerHTML=`<div class="cfh"><b>${esc(p.name)} Content Calendar</b><span class="sub">${p.rows.length} days · ${esc(p.platforms.join(', '))}${genBusy?' · Still writing…':''}</span><div class="act">${genBusy?'<button class="sm" data-act="stop">Stop</button>':''}<button class="sm send" data-cal="toposts" data-i="${CALP}">Turn into posts</button><button class="sm" data-cal="xls" data-i="${CALP}">Download Excel</button><button class="sm" data-cal="csv" data-i="${CALP}">Download CSV</button><button class="sm" data-cal="print" data-i="${CALP}">Print or save as PDF</button><button class="rm" data-cal="del" data-i="${CALP}">${CDEL?'Tap again to delete':'Delete'}</button><button class="sm" data-cal="toggle" data-i="${CALP}" aria-label="Close the calendar">Close</button></div></div><div class="cft" aria-hidden="true"><div class="cfti"></div></div><div class="cfb">${planTable(p,true)}</div>`;
