if(a==='save'){if(!PF.text.trim()){status('Write the post text first.',true);return}if(!PF.platforms.length){status('Pick at least one place to post.',true);return}PF.platforms.forEach(pf=>L.push({id:uid(),key:'',platform:pf,text:PF.text,when:PF.when,status:PF.when?'Scheduled':'Draft',media:PF.media,link:'',source:'',res:{}}));PF={platforms:PF.platforms,text:'',media:'',when:''};save();view();status('Saved. Find it under Your posts.')}
