const TPRE=()=>`You are a senior creative and marketing specialist at ${brand().name}, a Nigerian marketing and positioning consultancy. Write in plain, direct English with no hype and no jargon. Do not use markdown symbols such as ** or #. Use "- " for lists and plain numbered lines for steps. Money is in naira.\n`;
const TOOLS={
imggen:{title:'Image generation',blurb:'Make a picture from a description',intro:'Use Make a picture above to create it here. This writer helps you make a better description first: it gives three prompts, a designer brief, and the text to add over the picture.',fields:[['what','What is the picture of?','long','e.g. a pair of white sneakers on a lagos street at sunset'],['style','Style','text','e.g. clean, bold, photographic'],['colors','Brand colours','text','e.g. orange and charcoal'],['use','Where will it be used?','text','e.g. Instagram post, flyer'],['shape','Shape','select',['Square','Portrait','Landscape','Story (vertical)']]],req:['what'],btn:'Write the prompts',ext:'imggen',prompt:v=>TPRE()+`Write image-generation prompts.\nSubject: ${v.what}\nStyle: ${v.style||'open'}\nBrand colours: ${v.colors||'open'}\nUse: ${v.use||'open'}\nShape: ${v.shape||'Square'}\nGive: 1) three different ready-to-paste prompts, each one paragraph; 2) a one-paragraph brief a designer could follow; 3) the text, if any, that should be added over the picture afterwards, because generators spell badly.`},
imgedit:{title:'Image editing',blurb:'Crop, adjust, add text and save to the gallery',intro:'Use the picture editor above to crop, adjust, add text and save to the gallery. This writes extra step-by-step advice for a change you want.',fields:[['what','What needs to change?','long','e.g. remove the background, resize for Instagram, add our logo'],['tool','Which editor?','select',['Photopea','Canva','Adobe Express','Any']],['use','Where will it be used?','text','e.g. WhatsApp status, website banner']],req:['what'],btn:'Write the steps',ext:'imgedit',prompt:v=>TPRE()+`Write step-by-step editing instructions for a beginner.\nChange needed: ${v.what}\nEditor: ${v.tool||'Any'}\nUse: ${v.use||'open'}\nGive numbered steps, the best size in pixels for that use, the best file type to export, and two common mistakes to avoid.`},
vidgen:{title:'Video generation',blurb:'Script, scenes and prompts for a video',intro:'The workspace does not render video yet. This writes the script, the scene list, the voiceover and a prompt for each scene, ready for the video engine when it is added here.',fields:[['what','What is the video about?','long','e.g. launch of our new sneaker range'],['len','Length','select',['15 seconds','30 seconds','60 seconds','90 seconds']],['where','Where will it run?','text','e.g. TikTok, Instagram Reels, YouTube'],['tone','Tone','text','e.g. energetic, calm, funny']],req:['what'],btn:'Write the script',ext:'vidgen',prompt:v=>TPRE()+`Write a short video plan.\nTopic: ${v.what}\nLength: ${v.len||'30 seconds'}\nPlatform: ${v.where||'open'}\nTone: ${v.tone||'open'}\nGive: the hook (first 3 seconds); a scene list with, for each scene, the shot, the voiceover line, the on-screen text and the length; music mood; the closing call to action; and one short prompt per scene that can be pasted into an AI video generator.`},
videdit:{title:'Video editing',blurb:'Cut, rearrange, caption and export videos',intro:'Use the video editor above to cut, rearrange and caption. This writes an edit plan to follow: cuts, captions, pacing, sound and what to say.',fields:[['what','What footage do you have?','long','e.g. 6 phone clips of a product shoot, plus a voice note'],['goal','What should the final video do?','text','e.g. 30 second TikTok that sells the sneakers'],['tool','Which editor?','select',['CapCut','Clipchamp','Canva','Any']]],req:['what'],btn:'Write the edit plan',ext:'videdit',prompt:v=>TPRE()+`Write a video edit plan for a beginner.\nFootage: ${v.what}\nGoal: ${v.goal||'open'}\nEditor: ${v.tool||'Any'}\nGive: the order of clips and cuts with rough timings, caption text, pacing advice, sound advice, and the best export size and settings for the platform.`},
kw:{title:'Keywords',blurb:'Keyword ideas for a business or topic',intro:'This gives keyword ideas based on the business you describe. It cannot see search volumes or rankings. Check volumes in Google Keyword Planner or a similar tool before you build around any of them.',fields:[['biz','What does the business or page sell?','long','e.g. wedding photography in Abuja'],['place','Location','text','e.g. Abuja, Nigeria'],['who','Who is the customer?','text','e.g. couples planning a wedding']],req:['biz'],btn:'Find keyword ideas',prompt:v=>TPRE()+`Suggest SEO keyword ideas.\nBusiness: ${v.biz}\nLocation: ${v.place||'not given'}\nCustomer: ${v.who||'not given'}\nGive about 20 phrases grouped by what the searcher wants: wants to buy, wants to compare, wants to learn, wants something local. After each phrase, add a few words on what page it suits. Do not state search volumes, because you cannot know them.`},
aeo:{title:'AEO: answer engines',blurb:'Content that AI assistants quote as the answer',intro:'Answer engines such as ChatGPT, Gemini and Google AI Overviews pick short, clear, trustworthy answers. This writes answer-ready content: direct answers, a FAQ, plain facts about the business, and structured data. It cannot see what any answer engine says about you today.',fields:[['q','Question or topic to be the answer for','long','e.g. how much does a brand audit cost in Abuja?'],['biz','Business and what it does','text','e.g. a marketing and positioning consultancy'],['place','Location','text','e.g. Abuja, Nigeria']],req:['q'],btn:'Write answer-ready content',prompt:v=>TPRE()+`Write answer-engine optimisation (AEO) content.\nQuestion or topic: ${v.q}\nBusiness: ${v.biz||'not given'}\nLocation: ${v.place||'not given'}\nGive: 1) the question rewritten the way people type it, plus two close variations; 2) a direct answer of 40 to 60 words that can stand alone and starts with the answer; 3) six FAQ questions with short answers of two sentences each; 4) a short block of plain facts about the business (who, what, where, who it is for, what it costs if known) written so a machine can quote it; 5) the FAQ as FAQPage JSON-LD code; 6) five places to publish or earn mentions so the answer is found. Do not invent prices, awards or statistics. Mark anything the business must fill in with [fill in].`},
aeocheck:{title:'AEO check',blurb:'Is this page ready to be quoted as an answer?',intro:'Paste the text of a page and the question it should answer. This judges whether an answer engine could quote it: does it answer early, is it clear, is it structured, is it trustworthy. It cannot open the page or see real answer-engine results.',fields:[['text','Paste the page text','long','Headings and paragraphs'],['q','The question it should answer','text','e.g. what is a brand audit?']],req:['text','q'],btn:'Check answer readiness',prompt:v=>TPRE()+`Judge this page for answer-engine readiness, using only the text.\nQuestion: ${v.q}\nPage text:\n${v.text}\nGive: a score out of 10; whether a direct answer appears in the first 100 words; what is unclear or missing; whether headings are questions or clear labels; where evidence, names, dates or numbers are needed; the rewritten opening answer in 40 to 60 words; and the five most useful changes in order. Say clearly that you cannot see real answer-engine results.`},
meta:{title:'Page title and description',blurb:'Titles and descriptions that fit search results',intro:'Gives three options for the title (up to 60 characters) and the description (up to 155 characters) of a page.',fields:[['page','What is the page about?','long','e.g. our brand audit service for small businesses'],['key','Main keyword','text','e.g. brand audit Abuja'],['brand','Brand name','text',brand().name]],req:['page'],btn:'Write the options',prompt:v=>TPRE()+`Write SEO page titles and meta descriptions.\nPage: ${v.page}\nMain keyword: ${v.key||'none given'}\nBrand: ${v.brand||brand().name}\nGive three options. Each has a title of at most 60 characters and a description of at most 155 characters, with the character counts written beside them. Put the keyword near the front of the title.`},
outline:{title:'Article outline',blurb:'An outline for a blog post that can rank',intro:'Writes the headings and points for an article. You or the team write the article itself.',fields:[['key','Main keyword or topic','text','e.g. how to build a brand in Nigeria'],['who','Who is it for?','text','e.g. small business owners'],['goal','What should readers do after?','text','e.g. book a free session']],req:['key'],btn:'Write the outline',prompt:v=>TPRE()+`Write an article outline for SEO.\nKeyword or topic: ${v.key}\nReader: ${v.who||'not given'}\nGoal: ${v.goal||'not given'}\nGive: a title; the one-paragraph intro idea; headings with two to three points each; five questions readers ask, to answer at the end; ideas for what other pages to link to; and a call to action.`},
check:{title:'Check a page',blurb:'Review the text of a page for SEO',intro:'This cannot open pages or see rankings. Paste the text of the page and it reviews the writing, headings and keyword use. It will not comment on speed, links or technical SEO.',fields:[['text','Paste the page text','long','Headings, paragraphs, anything on the page'],['key','Main keyword','text','e.g. brand audit Abuja']],req:['text'],btn:'Check the page',prompt:v=>TPRE()+`Review this page text for on-page SEO, using only the text.\nMain keyword: ${v.key||'none given'}\nPage text:\n${v.text}\nGive: what is working; what is missing; whether the keyword appears in the title, first paragraph and headings; suggested headings; and the five most useful changes in order. Say clearly that you cannot judge speed, links or rankings.`}};
