function ieDraw(){const cv=$('#ie-canvas');if(!cv||!IEIMG)return;const o=IE.ops,rot=o.rot%360;let w=IEIMG.width,h=IEIMG.height;if(rot===90||rot===270)[w,h]=[h,w];
const t=document.createElement('canvas');t.width=w;t.height=h;const tc=t.getContext('2d');tc.translate(w/2,h/2);tc.rotate(rot*Math.PI/180);if(o.flip)tc.scale(-1,1);tc.drawImage(IEIMG,-IEIMG.width/2,-IEIMG.height/2);
let cw=w,ch=h;if(o.ratio!=='free'){const r=+o.ratio;if(w/h>r)cw=Math.round(h*r);else ch=Math.round(w/r)}const sx=Math.round((w-cw)/2),sy=Math.round((h-ch)/2),sc=Math.min(1,1600/Math.max(cw,ch));
cv.width=Math.round(cw*sc);cv.height=Math.round(ch*sc);const c=cv.getContext('2d');c.filter=`brightness(${o.bright}%) contrast(${o.contrast}%) saturate(${o.sat}%) grayscale(${o.gray?1:0})`;c.drawImage(t,sx,sy,cw,ch,0,0,cv.width,cv.height);c.filter='none';
if(o.text){const fs=Math.round(cv.height*o.tsize/100*1.6);c.font=`800 ${fs}px sans-serif`;c.textAlign='center';c.fillStyle=o.tcol;c.shadowColor=o.tcol==='#ffffff'?'rgba(0,0,0,.5)':'rgba(255,255,255,.5)';c.shadowBlur=fs/6;c.shadowOffsetY=fs/14;const y=o.tpos==='top'?fs*1.3:o.tpos==='middle'?cv.height/2+fs/3:cv.height-fs*.8;c.fillText(o.text,cv.width/2,y,cv.width*.94);c.shadowColor='transparent'}
if(o.logo){const L=logoSrc('l')||logoSrc('d');if(L){const lg=new Image();lg.onload=()=>{const lw=cv.width*.18,lh=lw*lg.height/lg.width;c.drawImage(lg,cv.width-lw-cv.width*.03,cv.height-lh-cv.width*.03,lw,lh)};lg.src=L}}}
