const CL=()=>{const h=W().home;if(!h.calls||typeof h.calls!=='object')h.calls={};const c=h.calls;if(!Array.isArray(c.numbers))c.numbers=[];if(!Array.isArray(c.triggers))c.triggers=[];if(!c.voice)c.voice={engine:'browser',name:'',rate:1,pitch:1,sample:'Hello, this is the assistant from the team. How can I help you today?'};if(!c.agent)c.agent={name:'',greeting:'',goal:'',rules:'',handoff:'',hours:'08:00 to 18:00'};return c};
const CLP=['Twilio','Africa\u2019s Talking','Vonage','WhatsApp Business','Your own phone line (SIP)','Other'],CLE=[['browser','Browser voices (free, works now)'],['elevenlabs','ElevenLabs'],['openai','OpenAI voices'],['other','Another voice service']],CLT=['A landing page form is sent','Someone picks an offer','A quotation is opened','A call was missed','A list I upload'];
