const BD=()=>{const h=W().home;if(!h.budget||typeof h.budget!=='object')h.budget={};const b=h.budget;if(!Array.isArray(b.plans))b.plans=[];if(!b.camp||typeof b.camp!=='object')b.camp={};if(!Array.isArray(b.log))b.log=[];if(b.alert==null)b.alert=80;if(b.test==null)b.test=15;return b};
